#!/usr/bin/env node
/**
 * `vsa-daemon` launcher — same pattern as the CLI's bin: re-exec Node with
 * `--experimental-transform-types` and a resolve hook mapping `./x.js`
 * specifiers to their `.ts` siblings, then import the daemon entry. The unit
 * files generated by `vsa daemon install` point ExecStart at this file.
 */
import { spawn } from 'node:child_process';

const hasTransform = process.execArgv.some((arg) => arg.includes('transform-types'));
if (!hasTransform) {
  const { fileURLToPath } = await import('node:url');
  const self = fileURLToPath(import.meta.url);
  const child = spawn(
    process.execPath,
    [
      '--experimental-transform-types',
      '--disable-warning=ExperimentalWarning',
      self,
      ...process.argv.slice(2),
    ],
    { stdio: 'inherit', env: process.env },
  );
  child.on('error', (error) => {
    console.error(String(error));
    process.exit(1);
  });
  child.on('exit', (code) => process.exit(code ?? 0));
} else {
  const { register } = await import('node:module');
  const { pathToFileURL } = await import('node:url');
  register(new URL('../tools/ts-js-map.mjs', import.meta.url), pathToFileURL('./'));
  const { daemonMain } = await import('../src/main.ts');
  await daemonMain(process.argv.slice(2));
}
